body:
I think I found the part that issues the slow down, it is the "templates" part:

```
var table   = Hogan.compile($.trim($('#table-template').text()));
var stats   = Hogan.compile($.trim($('#stats-template').text()));
var hits    = Hogan.compile($.trim($('#hit-template').text()));

search.addWidget(
    instantsearch.widgets.hits({
        container: '#table-container',
        templates: {
            empty: '<table class="table table-bordered table-suchergebnisliste"><tbody id="hits">No Results</tbody></table>',
            // Template MUST be a full <table>, see https://github.com/algolia/instantsearch.js/issues/770#issuecomment-184115613
            allItems:  function(data) {react!
                var stats_html  = stats.render(data);
                var hits_html   = '';
                $.each(data.hits, function(a, b) {
                    hits_html += hits.render(b);
                });
                var table_html  = table.render({stats: stats_html, hits: hits_html});

                return table_html;
            },
        },
        hitsPerPage:    15,
        transformData:  function(data) {
            data.processingTimeS = data.processingTimeMS / 100;
            return data;
        }
  })
);
```

When I disable the whole `template:` part, typing into the search box works as expected, it is rapid fast. It seems that the HTML generation is synchronous.
